#include <iostream>
#include <algorithm>

using namespace std;

const int MAX = 200001; // Adjusted size to avoid out-of-bounds
const long long INF = 1LL << 61;

long long a[MAX];

int main() {
    int n, k;
    while (cin >> n >> k) {
        if (n == 0) break;

        long long current_sum = 0; // Initialize current sum
        long long res = -INF; // Initialize result to negative infinity

        for (int i = 1; i <= n; ++i) {
            cin >> a[i];
            current_sum += a[i]; // Update cumulative sum

            // Calculate the maximum subarray sum for the window of size k
            if (i >= k) {
                long long window_sum = current_sum - (i > k ? a[i - k] : 0);
                res = max(res, window_sum); // Update result
            }
        }
        printf("%lld\n", res); // Using printf for consistency
    }
    return 0;
}

