const int MAX = 200000;
const long long INF = 1LL << 61;

int n, k;
long long a[MAX];

int main() {
    while (cin >> n >> k) {
        if (n == 0) break;
        for (int i = 0; i < MAX; ++i) a[i] = 0; // Manual initialization
        for (int i = 0; i < n; ++i) cin >> a[i + 1];
        for (int i = 0; i <= n; ++i) a[i + 1] += a[i];

        long long res = -INF;
        for (int i = 0; i + k <= n; ++i) {
            res = max(res, a[i + k] - a[i]);
        }
        cout << res << endl;
    }
    return 0;
}

