#include <iostream>
#include <cstring>
#include <deque>

using namespace std;

const int MAX = 200000;
const long long INF = 1LL << 61;

int n, k;
long long a[MAX];

int main() {
    while (cin >> n >> k) {
        if (n == 0) break;
        memset(a, 0, sizeof(a));
        for (int i = 0; i < n; ++i) cin >> a[i + 1];
        for (int i = 0; i <= n; ++i) a[i + 1] += a[i];

        long long res = -INF;
        deque<int> dq;
        for (int i = 0; i <= n; ++i) {
            while (!dq.empty() && dq.front() < i - k) dq.pop_front();
            while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
            dq.push_back(i);
            if (i >= k) res = max(res, a[dq.front()] - a[i - k]);
        }
        cout << res << endl;
    }
    return 0;
}

