        if (n == 0) break;
        vector<long long> a(n + 2, 0); // Vector for dynamic sizing
        for (int i = 1; i <= n; ++i) cin >> a[i];
        for (int i = 1; i <= n; ++i) a[i] += a[i - 1];

        long long res = -INF;
        for (int i = 0; i + k <= n; ++i) {
            res = max(res, a[i + k] - a[i]);
        }
        cout << res << endl;
    }
    return 0;
}

